sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {

  console.log('Cell link selected event:', event);

  // Get clicked column key
  var columnKey =
    event.columnKey ||
    event.field ||
    event.column?.key ||
    event.payload?.columnKey ||
    event.payload?.field ||
    '';

  // Only open modal for Comments column
  // Change 'comments' if your field name is different
  if (columnKey && columnKey !== 'comments') {
    return;
  }

  // Get record/row
  var record =
    event.record ||
    event.row ||
    event.item ||
    event.payload?.record ||
    event.payload?.row ||
    event.payload;

  if (!record) {
    console.log('No record found from event');
    return;
  }

  // Get sys_id
  var sysId = record.sys_id;

  if (sysId && typeof sysId === 'object') {
    sysId = sysId.value || sysId.displayValue;
  }

  if (!sysId) {
    console.log('No sys_id found:', record);
    return;
  }

  // Get existing comment
  var existingComment = '';

  if (record.comments) {
    existingComment = typeof record.comments === 'object'
      ? record.comments.value || record.comments.displayValue || ''
      : record.comments;
  }

  api.setState('selectedRecordSysId', sysId);
  api.setState('commentValue', existingComment || '');

  // Open custom modal
  // Replace custom_1 if your modal ID is different
  api.showModal('custom_1');
}
